function ordersView(){const rows=state.orders.filter(o=>(filter==='all'||o.biz===filter)&&(statusFilter==='all'||o.status===statusFilter)&&[o.id,o.sku,o.customer,o.channel].join(' ').toLowerCase().includes(orderQuery.toLowerCase()));return head('订单与渠道','OMNICHANNEL OPERATIONS','把平台、独立站与经销商，连接到同一条业务链。',btn(icon('download')+'导出订单','export')+btn(icon('plus')+'新建订单','new-order','primary'))+permissionNote('supply')+kpis([['订单金额',fmt(state.orders.reduce((s,o)=>s+amount(o),0)),'元','人民币 · 不含税','finance'],['待审核订单',state.orders.filter(o=>o.status==='待审核').length,'笔','TOB 信用与交付能力审核','orders'],['已生成凭证',state.journals.length,'笔','订单 → 结算 → 凭证 → 审计','check']])+`<section class="panel table-panel"><div class="toolbar"><input class="input" id="order-search" value="${esc(orderQuery)}" placeholder="搜索订单、客户或 SKU" aria-label="搜索订单"><select id="order-business" class="select" aria-label="订单业务"><option value="all">全部业务</option><option value="b2c" ${filter==='b2c'?'selected':''}>TOC 零售</option><option value="b2b" ${filter==='b2b'?'selected':''}>TOB 分销</option></select><select id="order-status" class="select" aria-label="订单状态"><option value="all">全部状态</option>${['待审核','待发货','待结算','已入账'].map(s=>`<option ${s===statusFilter?'selected':''}>${s}</option>`).join('')}</select><span class="subtext">共 ${rows.length} 笔</span></div><div class="table-wrap"><table><thead><tr><th>订单 / 创建时间</th><th>来源 / 业务</th><th>产品 / 数量</th><th>订单金额</th><th>状态</th><th>操作</th></tr></thead><tbody>${rows.map(o=>`<tr><td><button class="text-btn mono highlight" data-action="order-detail" data-id="${o.id}">${o.id}</button><small>${o.date}</small></td><td><strong>${o.channel}</strong><small>${businessLabel(o.biz)} · ${o.region}</small></td><td><strong>${product(o.sku).name}</strong><small>${o.sku} × ${o.qty}</small></td><td>${money(amount(o))}</td><td>${statusBadge(o.status)}</td><td>${btn(o.status==='待审核'?'审核订单':o.status==='待发货'?'确认发货':o.status==='待结算'?'前往结算':'查看凭证',o.status==='待结算'?'to-finance':o.status==='已入账'?'journal-detail':'order-next','small secondary',`data-id="${o.id}"`)}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">没有符合筛选条件的订单。可清空搜索或切换状态。</div>'}</div></section><section class="panel tabs-spacer"><div class="panel-head"><h2>统一订单履约链</h2><small>点击订单编号查看成本与证据链</small></div><div class="process-flow">${[['01','统一订单与客户'],['02','信用 / 库存审核'],['03','仓储发货与扣库'],['04','平台结算与归因'],['05','生成凭证与留痕']].map(x=>`<div class="process-node"><strong>${x[0]}</strong>${x[1]}</div>`).join(' → ')}</div><div class="subtext">TOB 订单采用预付 / 交付后结算口径。</div></section>`+footer()}
function financeView(){const pending=state.orders.filter(o=>o.status==='待结算');const variances=pending.reduce((s,o)=>s+o.variance,0);return head('财务中台','FINANCE & RECONCILIATION','每一笔经营结果，都能回到业务事实。',btn(icon('download')+'导出财务台账','export')+btn(icon('check')+(state.monthClosed?'本期已关账':'月结检查'),'close-month','primary'))+permissionNote('finance')+kpis([['待结算订单',pending.length,'笔',`待到账 ${money(pending.reduce((s,o)=>s+net(o),0))}`,'orders'],['待归因差异',fmt(variances),'元',variances?'需核实平台费用并审批':'所有已结算差异均已留痕','alert'],['已入账净额',fmt(+state.journals.reduce((s,j)=>s+net(state.orders.find(o=>o.id===j.order)),0).toFixed(2)),'元',`${state.journals.length} 张借贷平衡凭证`,'finance']])+`<div class="tabline"><button data-finance-tab="settlements" class="${financeTab==='settlements'?'active':''}">结算对账</button><button data-finance-tab="journals" class="${financeTab==='journals'?'active':''}">会计凭证 <span class="badge">${state.journals.length}</span></button><button data-finance-tab="profit" class="${financeTab==='profit'?'active':''}">单品损益</button></div>`+(financeTab==='settlements'?`<section class="panel table-panel"><div class="panel-head"><h2>结算工作台</h2><small>收入扣除平台费、履约费与已确认调整</small></div><div class="table-wrap"><table><thead><tr><th>结算 / 来源订单</th><th>渠道</th><th>订单收入</th><th>预计到账</th><th>实际到账</th><th>差异</th><th>操作</th></tr></thead><tbody>${pending.map(o=>`<tr><td><strong class="mono">ST-${o.id.slice(3)}</strong><small>${o.id}</small></td><td>${o.channel}</td><td>${money(amount(o))}</td><td>${money(net(o)+o.variance)}</td><td>${money(net(o))}</td><td>${o.variance?badge('-'+money(o.variance),'warn'):badge('一致','good')}</td><td>${btn('核对并入账','reconcile','small secondary',`data-id="${o.id}"`)}</td></tr>`).join('')}</tbody></table>${pending.length?'':'<div class="empty">暂无待结算订单。订单发货后将进入结算工作台。</div>'}</div></section><div class="notice tabs-spacer">核算口径：人民币、不含税；采用 SKU 固定标准成本。税务、汇兑、退款、收入确认及费用分摊需另行核定。</div>`:financeTab==='journals'?`<section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>凭证号</th><th>来源订单</th><th>借方合计</th><th>贷方合计</th><th>状态</th><th>追溯</th></tr></thead><tbody>${state.journals.map(j=>`<tr><td class="mono">${j.id}</td><td>${j.order}</td><td>${money(j.total)}</td><td>${money(j.total)}</td><td>${badge('借贷平衡','good')}</td><td>${btn('查看分录','journal-detail','small secondary',`data-id="${j.order}"`)}</td></tr>`).join('')}</tbody></table>${state.journals.length?'':'<div class="empty">完成一笔结算对账后，会计凭证会出现在这里。</div>'}</div></section>`:profitView())+footer()}
function profitView(){return `<section class="panel"><div class="panel-head"><h2>订单贡献利润分析</h2><small>贡献利润 = 收入 − 标准成本 − 平台费 − 履约费 − 调整</small></div><div class="table-wrap"><table><thead><tr><th>产品 / 订单</th><th>收入</th><th>标准成本</th><th>平台 + 履约</th><th>费用调整</th><th>贡献利润</th><th>利润率</th></tr></thead><tbody>${state.orders.map(o=>`<tr><td><strong>${product(o.sku).name}</strong><small>${o.id}</small></td><td>${money(amount(o))}</td><td>${money(cost(o))}</td><td>${money(fee(o)+freight(o))}</td><td>${money(o.variance)}</td><td class="positive">${money(profit(o))}</td><td>${(profit(o)/amount(o)*100).toFixed(1)}%</td></tr>`).join('')}</tbody></table></div><div class="insight">${icon('spark')}<span>这是订单层面的贡献利润，尚未扣除广告支出、研发费用及集团管理费用。未结算订单属于预计利润。</span></div></section>`}
function supplyView(){return head('供应链协同','SUPPLY CHAIN CONTROL','从需求预警，到采购入库与履约交付。',btn(icon('download')+'导出库存','export')+btn(icon('plus')+'创建采购单','new-po','primary'))+permissionNote('supply')+kpis([['可用库存',fmt(state.products.reduce((s,p)=>s+p.stock,0)),'件','扣除已发货数量 · 不含采购在途','supply'],['低于安全库存',state.products.filter(p=>p.stock<p.safety).length,'个 SKU','按品类日销与补货周期监控','alert'],['采购在途',fmt(state.purchaseOrders.filter(p=>p.status==='待收货').reduce((s,p)=>s+p.qty,0)),'件','审批通过后纳入在途，收货后转可用','orders']])+`<section class="panel table-panel"><div class="panel-head"><h2>库存与补货建议</h2><small>目标库存 = 30 天日均需求；建议量扣除有效采购</small></div><div class="table-wrap"><table><thead><tr><th>SKU / 产品</th><th>仓库</th><th>可用 / 安全</th><th>覆盖天数</th><th>标准成本</th><th>状态</th><th>操作</th></tr></thead><tbody>${state.products.map(p=>`<tr><td><strong>${p.name}</strong><small>${p.sku}</small></td><td>${p.warehouse}</td><td>${p.stock} / ${p.safety}</td><td>${(p.stock/p.daily).toFixed(1)} 天</td><td>${money(p.cost)}</td><td>${badge(p.stock<p.safety?'低于安全水位':p.stock/p.daily>60?'库龄关注':'库存健康',p.stock<p.safety?'warn':p.stock/p.daily>60?'purple':'good')}</td><td>${btn('生成补货','new-po','small secondary',`data-sku="${p.sku}"`)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel table-panel tabs-spacer"><div class="panel-head"><h2>采购订单</h2><small>发起 → 审批 → 收货 → 更新库存</small></div><div class="table-wrap"><table><thead><tr><th>采购单 / 供应商</th><th>物料</th><th>数量</th><th>采购金额</th><th>状态</th><th>操作</th></tr></thead><tbody>${state.purchaseOrders.map(p=>`<tr><td><strong class="mono">${p.id}</strong><small>${product(p.sku).supplier}</small></td><td>${p.sku}</td><td>${p.qty} 件</td><td>${money(p.qty*product(p.sku).cost)}</td><td>${statusBadge(p.status)}</td><td>${p.status==='已收货'?badge('库存已更新','good'):btn(p.status==='待审核'?'审批采购':'确认收货','po-next','small secondary',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table>${state.purchaseOrders.length?'':'<div class="empty">暂无采购订单。选择产品即可创建补货申请。</div>'}</div></section>`+footer()}
function productionView(){return head('研发与制造','PRODUCT LIFECYCLE & MANUFACTURING','连接 BOM 版本、生产执行与质量追溯。',btn(icon('plus')+'新建生产工单','new-mo','primary'))+permissionNote('supply')+`<div class="two-col"><section class="panel"><div class="panel-head"><h2>产品与 BOM 基线</h2><small>PLM → ERP → MES</small></div>${state.products.map(p=>`<div class="list-row"><div><strong>${p.name}</strong><div class="subtext">${p.bom} · ${p.family}</div></div>${btn('查看 BOM','bom','small secondary',`data-sku="${p.sku}"`)}</div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>研发变更控制</h2>${badge('变更已发布','good')}</div><div class="timeline"><div class="timeline-item"><strong>ECO-2026-018 · BT100 固件兼容性</strong><p>PLM：硬件 / 固件兼容矩阵更新，绑定 BOM-BT100-R3。</p></div><div class="timeline-item"><strong>评审：研发 → 质量 → 供应链</strong><p>旧版在制品保持原基线；新版物料用于新工单。</p></div><div class="timeline-item"><strong>生效批次：LOT-BT-2609</strong><p>质量检测结果与成品序列号关联，形成从研发到售后的追溯链。</p></div></div></section></div><section class="panel table-panel tabs-spacer"><div class="panel-head"><h2>生产与质量工作台</h2><small>本次入库按全批合格数量确认</small></div><div class="table-wrap"><table><thead><tr><th>工单</th><th>产品 / 版本</th><th>生产数量</th><th>执行单元</th><th>状态</th><th>操作</th></tr></thead><tbody>${state.workOrders.map(w=>`<tr><td class="mono">${w.id}</td><td><strong>${product(w.sku).name}</strong><small>BOM ${w.bom}</small></td><td>${w.qty} 台</td><td>${w.line}</td><td>${statusBadge(w.status)}</td><td>${w.status==='已完工'?btn('追溯批次','batch','small secondary',`data-id="${w.id}"`):btn(w.status==='待排产'?'下达生产':w.status==='生产中'?'报工完成':'质检并入库','mo-next','small secondary',`data-id="${w.id}"`)}</td></tr>`).join('')}</tbody></table></div></section>`+footer()}
function dataView(){let open=state.quality.filter(q=>q.status==='待处理').length;return head('数据治理','MASTER DATA & LINEAGE','统一物料、客户与账务，让经营口径可解释。',btn(icon('download')+'导出问题清单','export'))+permissionNote('admin')+kpis([['已对齐标准',3-open,'类','物料 / 客户 / 账务','database'],['待处理规则异常',open,'项','责任归属与修复记录全程保留','alert'],['主数据质量评分',(100-open*4.2).toFixed(1),'%','评分：100 − 待处理项 × 4.2','check']])+`<div class="tabline"><button data-data-tab="quality" class="${dataTab==='quality'?'active':''}">质量工作台</button><button data-data-tab="lineage" class="${dataTab==='lineage'?'active':''}">指标血缘</button><button data-data-tab="dictionary" class="${dataTab==='dictionary'?'active':''}">指标字典</button></div>`+(dataTab==='quality'?`<section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>规则 / 维度</th><th>发现的问题</th><th>来源链路</th><th>标准目标</th><th>状态</th><th>处置</th></tr></thead><tbody>${state.quality.map(q=>`<tr><td><strong>${q.id}</strong><small>${q.type}</small></td><td class="line-clamp" title="${q.desc}">${q.desc}</td><td>${q.source}</td><td class="mono">${q.target}</td><td>${statusBadge(q.status)}</td><td>${q.status==='待处理'?btn('审核映射','fix-data','small secondary',`data-id="${q.id}"`):badge('已记录修复','good')}</td></tr>`).join('')}</tbody></table></div></section>`:dataTab==='lineage'?`<section class="panel"><div class="panel-head"><h2>从报表指标追溯到来源字段</h2>${badge('收入口径 v1.2','purple')}</div><div class="data-lineage">${[['TOC / TOB 订单','order.net_amount'],['标准主数据','sku_id · entity_id'],['财务中台','确认收入 − 退款'],['经营数据集市','SUM(revenue_cny)'],['集团驾驶舱','营业收入 / 毛利']].map(x=>`<div class="lineage-box">${x[0]}<small>${x[1]}</small></div>`).join('<span class="lineage-arrow">→</span>')}</div><div class="two-col"><div><h3 class="section-title">转换规则</h3><p class="subtext">1. 订单金额扣除退款及税额。<br>2. 以集团汇率表转换到人民币。<br>3. 按财务确认日期归属账期。<br>4. 渠道、SKU、法人主体使用统一编码。</p></div><div><h3 class="section-title">责任与审计</h3><p class="subtext">业务责任：财务数据负责人<br>技术责任：数据平台负责人<br>变更流程：申请 → 评审 → 发布 → 版本留存<br>血缘模型：规划中。</p></div></div></section>`:`<section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>指标</th><th>统一口径</th><th>责任域</th><th>注意事项</th></tr></thead><tbody>${[['营业收入','已确认收入 − 退款，不含税','财务','统一人民币核算'],['经营毛利率','(净收入 − 销售成本) / 净收入','财务','不等于净利润率'],['订单贡献利润','收入 − 标准成本 − 平台费 − 履约费 − 调整','财务 + 运营','未扣广告及集团费用'],['ROAS','同窗口归因收入 / 广告支出','市场运营','仅包含已获得同意的可归因事件'],['库存覆盖天数','可用库存 / 预测日销','供应链','区别于财务库存周转天数']].map(x=>`<tr>${x.map(t=>`<td>${t}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`)+footer()}
function complianceView(){const controls=state.controls;return head('合规与审计','CONTROL, EVIDENCE & TRUST','把合规要求落实为控制、证据与可复核的操作。',btn(icon('download')+'导出审计证据','export','primary'))+`<div class="notice">按控制要求登记复核结论，并关联操作记录与证据索引。</div><div class="tabline"><button data-compliance-tab="controls" class="${complianceTab==='controls'?'active':''}">控制与证据</button><button data-compliance-tab="audit" class="${complianceTab==='audit'?'active':''}">操作审计 <span class="badge">${state.audit.length}</span></button><button data-compliance-tab="access" class="${complianceTab==='access'?'active':''}">角色与访问范围</button></div>`+(complianceTab==='controls'?`<div class="checklist">${controls.map(c=>`<section class="check-row"><div class="panel-head"><h3>${c.title}</h3>${statusBadge(c.status)}</div><div class="subtext">${c.id} · ${c.category} · ${c.owner}</div><p>证据要求：${c.evidence}</p><div class="actions">${badge(c.risk+'风险',c.risk==='高'?'warn':'')}${btn(c.status==='已留证'?'查看证据':'执行复核','control-review','small secondary',`data-id="${c.id}"`)}</div></section>`).join('')}</div>`:complianceTab==='audit'?`<section class="panel table-panel"><div class="panel-head"><h2>操作日志</h2><small>按时间、操作角色与业务对象追溯</small></div><div class="table-wrap"><table><thead><tr><th>时间 / 日志编号</th><th>角色</th><th>动作</th><th>对象</th><th>详情</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td>${esc(a.time)}<small>${a.id}</small></td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td><td class="mono">${esc(a.object)}</td><td class="line-clamp" title="${esc(a.detail)}">${esc(a.detail)}</td></tr>`).join('')}</tbody></table></div></section>`:`<section class="panel"><div class="panel-head"><h2>本地角色操作范围</h2><small>当前角色决定页面可执行的操作</small></div><div class="table-wrap"><table><thead><tr><th>角色</th><th>经营读取</th><th>订单 / 采购 / 生产</th><th>对账与入账</th><th>数据 / 基础设施</th></tr></thead><tbody>${[['IT 总监','允许','允许','允许','允许'],['财务经理','允许','只读','允许','只读'],['供应链经理','允许','允许','只读','只读'],['审计观察员','允许','只读','只读','只读']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="notice tabs-spacer">本地角色控制页面操作；制单、审批、出纳及系统管理的职责分离需另行配置。</div><div class="two-col"><div><h3 class="section-title">总部：聚合经营视图</h3><p class="subtext">汇总区域收入、成本、库存与质量指标；客户以代号显示。</p></div><div><h3 class="section-title">区域：目的限定的数据访问</h3><p class="subtext">按实体、区域和职责规划字段及导出范围，跨境数据访问需经专项审查。</p></div></div></section>`)+footer()}
function infrastructureView(){return head('全球基础设施','GLOBAL OPERATIONS & RESILIENCE','跨区域连接、集成健康与业务连续性。',btn(icon('refresh')+'恢复演练','restore','primary'))+permissionNote('admin')+`<div class="health-grid">${[['中国 · 深圳','核心业务与主数据','28','99.98','ERP / PLM / 财务集成'],['欧洲 · 法兰克福','欧洲区域数据域','42','99.95','区域客户数据就地处理'],['美国 · 弗吉尼亚','北美渠道与履约','36','99.97','北美订单与仓储集成']].map(x=>`<section class="health-node"><div class="panel-head"><h3>${x[0]}</h3>${badge('正常','good')}</div><p>${x[1]}</p><div class="latency">${x[2]}<small> ms · 链路延迟</small></div><div class="subtext">${x[4]}<br>月度可用率 ${x[3]}%</div></section>`).join('')}</div><section class="panel table-panel tabs-spacer"><div class="panel-head"><h2>业务系统集成</h2><small>消息处理与重试记录</small></div><div class="table-wrap"><table><thead><tr><th>系统</th><th>集成对象</th><th>成功消息</th><th>状态</th><th>操作</th></tr></thead><tbody>${state.integrations.map(i=>`<tr><td><strong>${i.name}</strong><small>Connector · ${i.id}</small></td><td>${i.domain}</td><td>${fmt(i.count)}</td><td>${statusBadge(i.status)}</td><td>${btn(i.status==='正常'?'同步数据':'重试失败消息','sync','small secondary',`data-id="${i.id}"`)}</td></tr>`).join('')}</tbody></table></div></section><div class="two-col tabs-spacer"><section class="panel"><div class="panel-head"><h2>备份与灾难恢复</h2>${badge(state.restored?'演练记录已生成':'待演练',state.restored?'good':'warn')}</div><div class="list-row"><span>目标 RPO / RTO</span><strong>15 分钟 / 2 小时</strong></div><div class="list-row"><span>演练恢复耗时</span><strong>${state.restored?'38 分钟':'尚未执行'}</strong></div><div class="list-row"><span>校验结果</span><span>${state.restored?'演练样本比对通过':'等待演练'}</span></div><p class="subtext">演练结果来自预置场景，不代表实际服务恢复。</p></section><section class="panel"><div class="panel-head"><h2>平台主体与技术治理</h2>${badge('合规运营','purple')}</div><div class="list-row"><span>店铺主体授权</span><span>实体 → 区域 → 岗位</span></div><div class="list-row"><span>账号访问与设备</span><span>MFA · 最小权限 · 专用设备</span></div><div class="list-row"><span>网络与操作记录</span><span>区域分区 · 访问审计</span></div><p class="subtext">遵守平台服务条款，通过主体授权、权限管理和可追溯操作降低关联风险。</p></section></div>`+footer()}
function adsView(){const ads=[{name:'TopScan · 北美独立站',region:'美国',spend:21000,revenue:84000,unattributed:12600},{name:'TC001 · 欧洲独立站',region:'欧洲',spend:18000,revenue:59400,unattributed:9800},{name:'BT100 · 北美零售活动',region:'美国',spend:12000,revenue:51600,unattributed:6800}].filter(x=>adRegion==='all'||x.region===adRegion);let spend=ads.reduce((s,a)=>s+a.spend,0),revenue=ads.reduce((s,a)=>s+a.revenue,0);return head('广告与归因','MARKETING ATTRIBUTION','把增长效率与用户同意，一起纳入经营判断。')+kpis([['广告支出',fmt(spend),'元','2026.09.20–09.26','finance'],['可归因收入',fmt(revenue),'元','净退款后收入 · 7 日点击归因','trend'],['广告投入产出比',(revenue/spend).toFixed(2),'ROAS','可归因收入 ÷ 广告支出','grid']])+`<section class="panel table-panel"><div class="panel-head"><h2>活动表现</h2><select class="select" id="ad-region" aria-label="广告区域"><option value="all">全部区域</option><option ${adRegion==='美国'?'selected':''}>美国</option><option ${adRegion==='欧洲'?'selected':''}>欧洲</option></select></div><div class="table-wrap"><table><thead><tr><th>活动</th><th>广告支出</th><th>归因收入</th><th>未归因收入</th><th>ROAS</th></tr></thead><tbody>${ads.map(a=>`<tr><td>${a.name}</td><td>${money(a.spend)}</td><td>${money(a.revenue)}</td><td>${money(a.unattributed)}</td><td class="positive">${(a.revenue/a.spend).toFixed(2)}</td></tr>`).join('')}</tbody></table></div><div class="insight">${icon('spark')}<span>未归因收入不计入 ROAS；归因窗口、币种与净收入口径保持一致。</span></div></section><div class="two-col tabs-spacer"><section class="panel"><div class="panel-head"><h2>营销同意与事件检查</h2>${badge(state.privacyConsent?'营销同意已授予':'营销追踪已拒绝',state.privacyConsent?'good':'warn')}</div><p class="subtext">检查当前会话的同意规则；拒绝追踪时阻断营销事件。</p><div class="actions">${btn('拒绝营销追踪','consent-deny',!state.privacyConsent?'primary':'')}${btn('允许营销追踪','consent-allow',state.privacyConsent?'primary':'')}</div><div class="notice tabs-spacer">当前 purchase 事件：<strong>${state.privacyConsent?'允许记录 · 写入本地日志':'阻断 · 不向任何营销端点发送'}</strong><br>同意文案版本 CMP-v1 · 目的：广告效果测量</div>${btn('测试一次购买事件','test-pixel','secondary')}</section><section class="panel"><div class="panel-head"><h2>订阅业务观察</h2>${badge('拟建能力','purple')}</div><div class="list-row"><span>订阅收入识别</span><span>设备销售与服务收入分离</span></div><div class="list-row"><span>服务履约期间</span><span>递延 → 按期间确认</span></div><div class="list-row"><span>关键经营指标</span><span>续费率 · 留存率 · 递延余额</span></div><p class="subtext">TOPDON 公开产品包含软件更新 / 订阅。订阅能力纳入后续规划，当前订单覆盖硬件业务。</p></section></div>`+footer()}
function strategyView(){return head('战略蓝图','STRATEGY & DELIVERY','围绕经营目标，规划集团数字化建设与交付。',btn(icon('play')+'业务流程导航','guide','primary'))+`<div class="tabline"><button data-strategy-tab="blueprint" class="${strategyTab==='blueprint'?'active':''}">建设蓝图</button><button data-strategy-tab="roadmap" class="${strategyTab==='roadmap'?'active':''}">交付路线与预算</button><button data-strategy-tab="assets" class="${strategyTab==='assets'?'active':''}">资产与供应商</button><button data-strategy-tab="research" class="${strategyTab==='research'?'active':''}">公司调研与依据</button></div>`+(strategyTab==='blueprint'?`<section class="panel"><div class="panel-head"><h2>以经营结果为牵引的分层架构</h2>${badge('建议目标架构','purple')}</div><div class="architecture">${[['经营决策',[['集团驾驶舱','收入 / 毛利 / 周转'],['经营分析','区域 / 渠道 / 产品'],['审计与合规','控制 / 证据 / 追溯']]],['业务中台',[['既有 TOC 中台','保持并演进'],['TOB 渠道贯通','合同 / 订单 / 应收'],['财务中台','对账 / 成本 / 月结']]],['产供销执行',[['PLM','BOM / 研发变更'],['MES','生产 / 质量'],['ERP + WMS','采购 / 库存 / 发运']]],['共同底座',[['统一主数据','物料 / 客户 / 账务'],['数据与集成','血缘 / 质量 / 接口'],['全球安全底座','区域数据 / 权限 / 灾备']]]].map(x=>`<div class="arch-layer"><div class="arch-label">${x[0]}</div><div class="arch-items">${x[1].map(n=>`<div class="arch-item">${n[0]}<small>${n[1]}</small></div>`).join('')}</div>`).join('')}</div><div class="insight">${icon('spark')}<span>建设建议：延续 TOC 能力，优先推进财务与供应链协同，以主数据和审计为共同基础。</span></div></section><div class="three-col tabs-spacer">${[['01','让财务有依据','订单、退款、费用、结算与成本同源；经营分析能穿透到凭证与来源单据。'],['02','让交付可预测','需求、采购、制造、库存与履约联动；通过例外管理推动业务闭环。'],['03','让治理能证明','职责、权限、主数据与变更均可追溯；合规要求有负责人和可验证证据。']].map(x=>`<section class="panel"><div class="eyebrow">${x[0]}</div><h2>${x[1]}</h2><p class="subtext">${x[2]}</p></section>`).join('')}</div>`:strategyTab==='roadmap'?`<div class="roadmap">${[['0–30 天','业务与数据盘点','梳理订单到收款、采购到付款；建立系统地图、主数据字典、风险清单。','产出：现状基线与优先级'],['31–90 天','财务链路试点','先接入一个区域与渠道，完成结算对账、成本口径、凭证和审计闭环。','验收：样本可追溯、差异可解释'],['3–6 个月','产供销协同','统一 SKU / BOM，打通 ERP、WMS、MES、PLM，建立补货与交付看板。','验收：试点库存与单据一致'],['6–12 个月','集团化治理','扩展多主体多币种，完善安全、区域数据、内控证据与管理制度。','验收：按职责和区域稳定运营']].map(x=>`<section class="phase"><span class="phase-date">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p><div class="owner">${x[3]}</div></section>`).join('')}</div><section class="panel table-panel tabs-spacer"><div class="panel-head"><h2>项目预算治理</h2><small>单位：万元</small></div><div class="table-wrap"><table><thead><tr><th>项目 / 责任团队</th><th>批准预算</th><th>已发生</th><th>未结承诺</th><th>可用预算</th><th>阶段</th><th>操作</th></tr></thead><tbody>${state.projects.map(p=>`<tr><td><strong>${p.name}</strong><small>${p.owner}</small></td><td>${p.budget}</td><td>${p.spent}</td><td>${p.committed}</td><td>${p.budget-p.spent-p.committed}</td><td>${badge(p.phase,p.phase==='进行中'?'purple':'')}</td><td>${btn('申请投入','budget','small secondary',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div><div class="subtext">建议组织：业务产品负责人 + 财务 / 供应链产品经理 + 集成与数据工程 + 安全运维；内外部供应商按里程碑验收。</div></section>`:strategyTab==='assets'?`<div class="two-col"><section class="panel"><div class="panel-head"><h2>IT 资产台账</h2><small>生命周期与责任归属</small></div>${[['AS-001 · 核心云资源','平台运维负责人','运行中 · 2027.03 续费'],['AS-002 · 研发工作站池','研发 IT 负责人','运行中 · 2027.06 保修到期'],['AS-003 · 区域备份服务','基础设施负责人','运行中 · 按月校验恢复'],['AS-004 · 专用运营终端','区域运营负责人','授权清单关联 · 季度复核']].map(x=>`<div class="list-row"><div><strong>${x[0]}</strong><div class="subtext">${x[1]}<br>${x[2]}</div></div>${btn('详情','asset','small',`data-id="${x[0].slice(0,6)}"`)}</div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>供应商履约</h2><small>合同周期与服务等级</small></div>${[['集成服务商 A','年度合同 ¥480,000','SLA 99.9% · 2027.03 到期'],['基础设施服务商 B','年度合同 ¥360,000','SLA 99.95% · 2027.01 到期'],['安全服务商 C','年度合同 ¥180,000','P1 响应 ≤30 分钟 · 季度评估']].map(x=>`<div class="list-row"><div><strong>${x[0]}</strong><div class="subtext">${x[1]}<br>${x[2]}</div></div>${badge('按期履约','good')}</div>`).join('')}<div class="notice tabs-spacer">合同、预算承诺、资产责任人与服务等级关联，避免仅按采购价格评估供应商。</div></section></div>`:researchView())+footer()}
function researchView(){return `<section class="panel"><div class="panel-head"><h2>公司与岗位判断</h2><small>研究日期：2026.09.26</small></div><p class="research-lead">鼎匠创新 / TOPDON 的数字化命题，是把全球硬件与软件业务的增长，转化为可核算、可协同、可审计的经营体系。</p><div class="two-col"><div><h3 class="section-title">公开资料可确认</h3><p class="subtext">鼎匠创新官方旧站直接标注 TOPDON 及公司名称；公开产品覆盖汽车诊断、电池服务与热成像。区域官网展示直营电商与经销商网络。官方服务条款涉及多个区域实体，隐私声明强调区域数据管理。</p></div><div><h3 class="section-title">由 JD 推导的建设重点</h3><p class="subtext">既有 TOC 中台继续演进，财务中台与供应链数字化优先；统一物料、客户和账务标准；连接 ERP / WMS / MES / PLM；补齐内控证据、全球基础设施与团队交付治理。</p></div></div><div class="notice warn">待核实：IPO 阶段、系统供应商、预算、组织及仓库配置。公开研究不代表企业内部经营情况。</div>${[['鼎匠创新官方旧站','公司名称、TOPDON 品牌、全渠道与敏捷供应链','https://www.lenkor.cn/'],['TOPDON 欧洲官方介绍','区域服务与经销商网络','https://eu.topdon.com/pages/about-topdon-europe'],['TOPDON 官方服务条款','区域经营实体、产品与订阅服务','https://m.topdon.com/about_terms'],['TOPDON 官方隐私声明','区域数据治理与个人信息处理原则','https://m.topdon.com/about_privacy'],['TOPDON 官方产品目录','Phoenix、BT100、TC001 等真实产品型号','https://au.topdon.com/collections/all'],['TOPDON ONE 产品','软件更新与订阅业务线索','https://www.topdon.com/products/one']].map(x=>`<div class="source-item"><strong><a href="${x[2]}" target="_blank" rel="noopener noreferrer">${x[0]} ↗</a></strong><small>${x[1]}</small></div>`).join('')}<div class="subtext">岗位依据：IT 总监 JD 截图。引用来自公开资料；本产品与 TOPDON 无官方授权或业务系统连接。</div></section>`}
